	@Test
	void patternLocalFiniteFilterUsesMappedStatisticsAcrossPlanningScopes(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc"));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			IRI predicate = VF.createIRI("urn:test:correlated:shared-filter-surface-predicate");
			Value retained = VF.createLiteral("retained");
			try (var connection = repository.getConnection()) {
				connection.add(VF.createIRI("urn:test:correlated:shared-filter-subject-1"), predicate, retained);
				connection.add(VF.createIRI("urn:test:correlated:shared-filter-subject-2"), predicate,
						VF.createLiteral("discarded"));
			}
			LmdbPlannerAwait.rebuildSketchesIfEnabled(store);

			StatementPattern pattern = new StatementPattern(
					Var.of("subject"), Var.of("predicate", predicate), Var.of("value"));
			Compare condition = new Compare(Var.of("value"), new ValueConstant(retained), Compare.CompareOp.EQ);
			LmdbEstimatorRuntime runtime = ((LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics()).estimatorRuntime();
			LmdbExactFiniteSurfaceCache cache = runtime.frontierSettings().exactFiniteSurfaceCache();

			long hitsBefore = cache.hits();
			try (var ignored = runtime.beginScope()) {
				assertEquals(0.5d, runtime.patternFilterPass(condition, pattern).orElseThrow().getPassRatio(), 0.0d);
			}
			try (var ignored = runtime.beginScope()) {
				assertEquals(0.5d, runtime.patternFilterPass(condition, pattern).orElseThrow().getPassRatio(), 0.0d);
			}

			assertEquals(hitsBefore, cache.hits(),
					"authoritative mapped filter probes must not enumerate or cache exact statement surfaces");
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void completedExactSurfaceRebindsAlphaEquivalentVariablesAcrossPlanningScopes(@TempDir File dataDir)
			throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc"));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			IRI subject = VF.createIRI("urn:test:correlated:alpha-surface-subject");
			IRI predicate = VF.createIRI("urn:test:correlated:alpha-surface-predicate");
			IRI object = VF.createIRI("urn:test:correlated:alpha-surface-object");
			try (var connection = repository.getConnection()) {
				connection.add(subject, predicate, object);
			}

			LmdbEstimatorRuntime runtime = ((LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics()).estimatorRuntime();
			LmdbExactFiniteSurfaceCache cache = runtime.frontierSettings().exactFiniteSurfaceCache();
			FiniteRelationEstimate firstRelation = FiniteRelationEstimate.fromRows(
					List.of("subject"), List.of(List.of(subject)), "frontier-correlation");
			StatementPattern firstKernel = new StatementPattern(
					Var.of("subject"), Var.of("predicate", predicate), Var.of("object"));
			FiniteRelationEstimate renamedRelation = FiniteRelationEstimate.fromRows(
					List.of("renamedSubject"), List.of(List.of(subject)), "renamed-correlation");
			StatementPattern renamedKernel = new StatementPattern(
					Var.of("renamedSubject"), Var.of("renamedPredicate", predicate), Var.of("renamedObject"));

			LmdbFiniteJoinSurfaceEstimator.SurfaceEstimate first;
			try (var ignored = runtime.beginScope()) {
				first = runtime.exactCorrelatedSurface(
						"first-state", firstRelation, firstKernel, EstimationTier.DECISION_EXACT).orElseThrow();
			}
			long hitsBefore = cache.hits();
			LmdbFiniteJoinSurfaceEstimator.SurfaceEstimate renamed;
			try (var ignored = runtime.beginScope()) {
				renamed = runtime.exactCorrelatedSurface(
						"renamed-state", renamedRelation, renamedKernel, EstimationTier.DECISION_EXACT)
						.orElseThrow();
			}

			assertEquals(hitsBefore + 1L, cache.hits());
			assertEquals(first.surfaceRows(), renamed.surfaceRows());
			assertEquals(List.of("renamedSubject", "renamedObject"), renamed.relation().variables());
			assertEquals(object, renamed.relation().frequencies().keySet().iterator().next().get(1));
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void completedExactSurfaceDoesNotCrossAStoreDataRevision(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc"));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			IRI subject = VF.createIRI("urn:test:correlated:revision-surface-subject");
			IRI predicate = VF.createIRI("urn:test:correlated:revision-surface-predicate");
			try (var connection = repository.getConnection()) {
				connection.add(subject, predicate, VF.createIRI("urn:test:correlated:revision-object-1"));
			}

			FiniteRelationEstimate relation = FiniteRelationEstimate.fromRows(
					List.of("subject"), List.of(List.of(subject)), "frontier-correlation");
			StatementPattern accessKernel = new StatementPattern(
					Var.of("subject"), Var.of("predicate", predicate), Var.of("object"));
			LmdbEstimatorRuntime runtime = ((LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics()).estimatorRuntime();
			LmdbFiniteJoinSurfaceEstimator.SurfaceEstimate first;
			try (var ignored = runtime.beginScope()) {
				first = runtime.exactCorrelatedSurface(
						"first-state", relation, accessKernel, EstimationTier.DECISION_EXACT).orElseThrow();
			}
			try (var connection = repository.getConnection()) {
				connection.add(subject, predicate, VF.createIRI("urn:test:correlated:revision-object-2"));
			}
			LmdbFiniteJoinSurfaceEstimator.SurfaceEstimate changed;
			try (var ignored = runtime.beginScope()) {
				changed = runtime.exactCorrelatedSurface(
						"changed-state", relation, accessKernel, EstimationTier.DECISION_EXACT).orElseThrow();
			}

			assertNotSame(first, changed);
			assertEquals(1.0d, first.surfaceRows());
			assertEquals(2.0d, changed.surfaceRows());
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void correlatedRelationPreservesMultiColumnTuplePairing(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc"));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			IRI firstSubject = VF.createIRI("urn:test:correlated:first-subject");
			IRI secondSubject = VF.createIRI("urn:test:correlated:second-subject");
			IRI firstPredicate = VF.createIRI("urn:test:correlated:first-predicate");
			IRI secondPredicate = VF.createIRI("urn:test:correlated:second-predicate");
			try (var connection = repository.getConnection()) {
				connection.add(firstSubject, firstPredicate, VF.createIRI("urn:test:correlated:first-object"));
				connection.add(secondSubject, secondPredicate, VF.createIRI("urn:test:correlated:second-object"));
				for (int index = 0; index < 10; index++) {
					connection.add(firstSubject, secondPredicate,
							VF.createIRI("urn:test:correlated:cross-a:" + index));
					connection.add(secondSubject, firstPredicate,
							VF.createIRI("urn:test:correlated:cross-b:" + index));
				}
			}

			Map<List<Value>, Double> pairs = new LinkedHashMap<>();
			pairs.put(List.of(firstSubject, firstPredicate), 1.0d);
			pairs.put(List.of(secondSubject, secondPredicate), 1.0d);
			FiniteRelationEstimate relation = FiniteRelationEstimate.fromFrequencies(
					List.of("subject", "predicate"), pairs, "frontier-correlation");
			StatementPattern accessKernel = new StatementPattern(
					Var.of("subject"), Var.of("predicate"), Var.of("object"));

			Object runtime = ((LmdbEvaluationStatistics) store.getBackingStore().getEvaluationStatistics())
					.estimatorRuntime();
			var method = runtime.getClass()
					.getDeclaredMethod("exactCorrelatedSurface", FiniteRelationEstimate.class,
							org.eclipse.rdf4j.query.algebra.TupleExpr.class);
			method.setAccessible(true);
			Optional<?> estimated = (Optional<?>) method.invoke(runtime, relation, accessKernel);
			assertTrue(estimated.isPresent());
			Object surface = estimated.orElseThrow();
			assertEquals(2.0d, number(surface, "surfaceRows"));
			assertEquals(2.0d, number(surface, "prefixRows"));
			assertEquals(2.0d, number(surface, "matchedPrefixRows"));
			assertEquals(2.0d, number(surface, "scannedRows"));
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void exactSurfaceSeparatesMatchedOuterMultiplicityFromRhsFanout(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc"));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			IRI matchedSubject = VF.createIRI("urn:test:correlated:matched-subject");
			IRI unmatchedSubject = VF.createIRI("urn:test:correlated:unmatched-subject");
			IRI predicate = VF.createIRI("urn:test:correlated:predicate");
			try (var connection = repository.getConnection()) {
				connection.add(matchedSubject, predicate, VF.createIRI("urn:test:correlated:first-object"));
				connection.add(matchedSubject, predicate, VF.createIRI("urn:test:correlated:second-object"));
				connection.add(unmatchedSubject, VF.createIRI("urn:test:correlated:unrelated-predicate"),
						VF.createIRI("urn:test:correlated:unrelated-object"));
			}

			Map<List<Value>, Double> frequencies = new LinkedHashMap<>();
			frequencies.put(List.of(matchedSubject), 3.0d);
			frequencies.put(List.of(unmatchedSubject), 2.0d);
			FiniteRelationEstimate relation = FiniteRelationEstimate.fromFrequencies(
					List.of("subject"), frequencies, "frontier-correlation");
			StatementPattern accessKernel = new StatementPattern(
					Var.of("subject"), Var.of("predicate", predicate), Var.of("object"));

			Object runtime = ((LmdbEvaluationStatistics) store.getBackingStore().getEvaluationStatistics())
					.estimatorRuntime();
			var method = runtime.getClass()
					.getDeclaredMethod("exactCorrelatedSurface", FiniteRelationEstimate.class,
							org.eclipse.rdf4j.query.algebra.TupleExpr.class);
			method.setAccessible(true);
			Optional<?> estimated = (Optional<?>) method.invoke(runtime, relation, accessKernel);
			assertTrue(estimated.isPresent());
			Object surface = estimated.orElseThrow();
			assertEquals(6.0d, number(surface, "surfaceRows"));
			assertEquals(5.0d, number(surface, "prefixRows"));
			assertEquals(3.0d, number(surface, "matchedPrefixRows"));
		} finally {
			repository.shutDown();
		}
	}

	private static double number(Object target, String accessor) throws Exception {
		var method = target.getClass().getDeclaredMethod(accessor);
		method.setAccessible(true);
		return ((Number) method.invoke(target)).doubleValue();
	}
